<?php
declare(strict_types=1);
/** Actual local manifest production; semantic/provider authority remains denied. */
final class ProductFactoryDualAssetAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 public function testActualManifestProducesCustomerAndMarketingBytesWithOnlyCustomerFilesInZip():void {
  $factory=new DigiForge\ProductFactory\Repository();$opp=$factory->create('opportunity',['title'=>'Dual asset local fixture']);self::assertNotWPError($opp);$family=$factory->create('product_family',['opportunity_id'=>$opp['id'],'name'=>'Dual fixture']);self::assertNotWPError($family);$product=$factory->create('product',['product_family_id'=>$family['id'],'name'=>'Dual fixture']);self::assertNotWPError($product);$version=$factory->create('product_version',['product_id'=>$product['id'],'version_label'=>'fixture-v1']);self::assertNotWPError($version);
  $manifest=['product_assets'=>[['asset_key'=>'customer-guide','filename'=>'customer-guide.txt','format'=>'txt','purpose'=>'Customer guide','content'=>'Welcome guide with complete local fixture instructions.']], 'marketing_assets'=>[['asset_key'=>'listing-preview','filename'=>'listing-preview.txt','format'=>'txt','purpose'=>'Listing preview only','content'=>'Listing preview for the customer guide.']]];
  $developed=['product'=>$product,'product_version'=>$version,'spec'=>['product_name'=>'Dual fixture','asset_requirements'=>['package_filename'=>'customer-fixture.zip']]];$calls=0;$http=static function()use(&$calls){$calls++;return new WP_Error('offline_fixture','Provider forbidden.');};add_filter('pre_http_request',$http);
  try{$result=(new DigiForge\ProductFactory\Orchestrator())->build(1,['shop'=>'digital','_developed'=>$developed,'_manifest_ai'=>['payload'=>$manifest]],'u3-repair-dual-'.wp_generate_uuid4());}finally{remove_filter('pre_http_request',$http);}
  self::assertWPError($result);self::assertSame('ai_generation_safety_locked',$result->get_error_code(),'Producing local bytes never grants semantic generation authority.');self::assertSame(0,$calls);
  global $wpdb;$rows=$wpdb->get_results($wpdb->prepare('SELECT s.asset_key,s.content_requirements,r.storage_reference,r.checksum_sha256 FROM '.DigiForge\Database\Tables::asset_specs().' s INNER JOIN '.DigiForge\Database\Tables::asset_revisions().' r ON r.asset_spec_id=s.id WHERE s.product_version_id=%d',$version['id']),ARRAY_A);self::assertIsArray($rows);$byKey=array_column($rows,null,'asset_key');
  foreach(['customer-guide'=>'product','listing-preview'=>'marketing']as $key=>$group){self::assertArrayHasKey($key,$byKey);$record=$byKey[$key];self::assertSame($group,json_decode($record['content_requirements'],true)['group']);$path=DigiForge\ProductFactory\AssetStorage::absolutePath($record['storage_reference']);self::assertNotNull($path);self::assertSame($record['checksum_sha256'],hash_file('sha256',$path));self::assertGreaterThan(0,filesize($path));}
  self::assertArrayHasKey('customer-package',$byKey);$archive=DigiForge\ProductFactory\AssetStorage::absolutePath($byKey['customer-package']['storage_reference']);self::assertNotNull($archive);$zip=new ZipArchive();self::assertTrue($zip->open($archive));try{self::assertNotFalse($zip->locateName('customer-guide.txt'));self::assertFalse($zip->locateName('listing-preview.txt'));self::assertFalse($zip->locateName('DELIVERY-MANIFEST.json'));}finally{$zip->close();}
  self::assertTrue(DigiForge\Core\Settings::safety_locked());self::assertFalse(DigiForge\Core\Settings::get('automation_armed',false));
 }
}
